// CPL Pathways tab — renderer.
//
// STATIC consumer asset (NOT regenerated by excel_to_dashboard.py), lazy-loaded
// by the inline boot in the tab shell on first activation of #tab-cpl-pathways.
//
// Purpose: audience-facing degree-pathway course maps that show, for a specific
// college program, which required courses an incoming student can clear through
// CPL — apprenticeship articulations already live in the MAP platform (✓, no
// classroom seat time) and CLEP exam options for GE requirements (◆, per the
// CCCCO systemwide exam-credit charts, ESLEI 24-35). Built for the California
// Apprenticeship Council presentation (2026-08-13): the first pathway is
// Cerritos College's Field Ironworker Supervisor baccalaureate (fall 2027),
// where journeyworker ironworkers arrive with 30+ units of CPL on day one.
// The pathway DEFINITIONS live in cpl_pathways_data.js (curated, static); the
// ✓ marks are DERIVED at render time from the live CER dataset
// (credential_reference_data.js, regenerated daily), so the picture tracks the
// MAP platform as colleges add articulations. Baked fallbacks cover a CER load
// failure, with an honest "live data unavailable" note.
//
// Self-contained behind the CONFIG block (the map_export.js / map_users.js
// pattern). Scoped CSS injected from JS so both HTMLs are covered without a
// Rule-4 mirror. All DOM is built via createElement/textContent — no innerHTML
// with data (XSS safety; CodeQL js/xss).
(function () {
  "use strict";

  var ROOT_ID = "cpl-pathways-root";
  // Directory adoption-pool: how many rows show before the "Show all N" toggle.
  var DIR_POOL_CAP = 20;

  // ── Config (anon key is public + RLS-gated; mirrors map_export.js) ──────
  // Quick-Adopt intake: cpl_adoption_interest is anon INSERT-only (no public
  // SELECT — contact info is never publicly readable). Schema of record:
  // kb/supabase_adoption_interest.sql.
  var SUPABASE_URL = "https://hvuwhnbuahrtptokpqfh.supabase.co";
  var SUPABASE_ANON = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imh2dXdobmJ1YWhydHB0b2twcWZoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzU1NzI0ODEsImV4cCI6MjA5MTE0ODQ4MX0.p0q-93iTM0GkF2z8_q7Vvl1tsX9SFGMM-W7Wdx7WfmM";
  var ADOPT_INTAKE = SUPABASE_URL + "/rest/v1/cpl_adoption_interest";

  // ── ⚡ Quick Adopt intake (v1: records the request; the CPL team routes it.
  //    Re-point at the MAP platform's authenticated adoption flow when the
  //    Exhibit Module exposes one.) ──────────────────────────────────────────
  function buildQuickAdopt(prog, row) {
    var wrap; // assigned below (el() is declared later; function hoisting covers calls)
    wrap = el("div", "cplpw-qa");
    var go = document.createElement("button");
    go.type = "button";
    go.className = "go";
    go.textContent = "⚡ Quick Adopt";
    go.title = "Ask the CPL team to bring this articulation to your college — records a request they follow up with your curriculum office.";
    var form = el("form", "cplpw-qa-form");
    form.style.display = "none";
    function input(name, ph, required, type) {
      var i = document.createElement("input");
      i.type = type || "text";
      i.name = name;
      i.placeholder = ph + (required ? " *" : "");
      i.setAttribute("maxlength", "200");
      return i;
    }
    var college = input("adopter_college", "Your college", true);
    var name = input("contact_name", "Your name", false);
    var email = input("contact_email", "Work email", true, "email");
    var note = document.createElement("textarea");
    note.name = "note";
    note.placeholder = "Anything the team should know (optional)";
    note.setAttribute("maxlength", "2000");
    var err = el("span", "cplpw-qa-err", "");
    var send = document.createElement("button");
    send.type = "submit";
    send.className = "go";
    send.textContent = "Send adoption request";
    var rowEl = el("div", "row", [send, err]);
    form.appendChild(college); form.appendChild(name); form.appendChild(email);
    form.appendChild(note);
    form.appendChild(el("div", "cplpw-qa-note",
      "v1: this records the request for the CPL team (contact info goes only to them — it is not publicly readable). The one-click in-MAP adoption lands when the MAP Exhibit Module exposes its authenticated flow."));
    form.appendChild(rowEl);
    go.addEventListener("click", function () {
      form.style.display = form.style.display === "none" ? "" : "none";
    });
    form.addEventListener("submit", function (ev) {
      ev.preventDefault();
      err.textContent = "";
      if (String(college.value).trim().length < 2) { err.textContent = "College is required."; return; }
      if (String(email.value).indexOf("@") < 1) { err.textContent = "A work email is required."; return; }
      var creds = (row.adoptOptions || []).map(function (o) { return o.credential; });
      var precedent = (row.adoptOptions || []).map(function (o) {
        return o.credential + ": " + o.lines.map(function (l) {
          return l.college + " " + l.code + (l.units != null ? " (" + fmtU(l.units) + "u)" : "");
        }).join("; ");
      }).join(" | ").slice(0, 1200);
      send.disabled = true;
      fetch(ADOPT_INTAKE, {
        method: "POST",
        headers: {
          "apikey": SUPABASE_ANON,
          "Authorization": "Bearer " + SUPABASE_ANON,
          "Content-Type": "application/json",
          "Prefer": "return=minimal",
        },
        body: JSON.stringify({
          program_id: prog.id || "unknown",
          program_label: (prog.college ? prog.college + " — " : "") + (prog.program || ""),
          course_code: row.code || null,
          course_title: row.title || "(course)",
          credentials: creds.join(" | ").slice(0, 600) || "(unspecified)",
          precedent: precedent || null,
          adopter_college: String(college.value).trim().slice(0, 120),
          contact_name: String(name.value).trim().slice(0, 120) || null,
          contact_email: String(email.value).trim().slice(0, 200),
          note: String(note.value).trim().slice(0, 2000) || null,
        }),
      }).then(function (r) {
        if (!r.ok) throw new Error("intake " + r.status);
        var ok = el("div", "cplpw-qa-ok", "✓ Request recorded — the CPL team will follow up with your curriculum office.");
        wrap.replaceChild(ok, form);
        go.style.display = "none";
      }).catch(function () {
        send.disabled = false;
        err.textContent = "Could not record the request — try again, or email the CPL team.";
      });
    });
    wrap.appendChild(go);
    wrap.appendChild(form);
    return wrap;
  }

  // ── Pathway status stages ─────────────────────────────────────────────────
  // The shipped default comes from the pathway's `stage` in cpl_pathways_data.js
  // (falling back to discussion-draft — never accidentally present a mock-up as
  // Active). The on-page selector is a per-browser VIEW override (localStorage)
  // so Sam can flip the label live while presenting; the published default only
  // changes by editing the data file.
  var STAGES = [
    { id: "discussion-draft", label: "Discussion Draft", glyph: "📝", cls: "draft",
      big: "DISCUSSION DRAFT",
      note: "A mock-up for feedback — not an official college publication. The CPL ✓ marks are live from the MAP platform; the pathway itself is a concept for discussion." },
    { id: "active", label: "Active", glyph: "✓", cls: "active",
      big: "ACTIVE PATHWAY",
      note: "This pathway is live — students are advised under it." },
    { id: "tabled", label: "Tabled", glyph: "⏸", cls: "tabled",
      big: "TABLED",
      note: "This pathway is parked — kept for reference, not currently moving." },
  ];
  var STAGE_BY_ID = {};
  STAGES.forEach(function (s) { STAGE_BY_ID[s.id] = s; });

  function stageKey(prog) { return "cplPathwaysStage." + (prog.id || "default"); }
  function getStage(prog) {
    try {
      var v = window.localStorage.getItem(stageKey(prog));
      if (v && STAGE_BY_ID[v]) return v;
    } catch (e) { /* storage unavailable — fall through to the shipped default */ }
    return (prog.stage && STAGE_BY_ID[prog.stage]) ? prog.stage : "discussion-draft";
  }
  function setStage(prog, id) {
    try { window.localStorage.setItem(stageKey(prog), id); } catch (e) { /* view-only nicety */ }
  }

  // ── Scoped CSS (var(--token) only — no raw hex) ──────────────────────────
  var CSS_ID = "cpl-pathways-css";
  var CSS = [
    ".cplpw { color: var(--text-body); max-width: 1080px; margin: 0 auto; }",
    /* Status toolbar (selector + PDF) — above the fold */
    ".cplpw-toolbar { display:flex; flex-wrap:wrap; gap:10px; align-items:center; margin: 12px 0 4px; }",
    ".cplpw-toolbar .lbl { font-size:.76rem; font-weight:700; color: var(--text-muted); letter-spacing:.04em; text-transform:uppercase; }",
    ".cplpw-stagesel { display:inline-flex; border:1px solid var(--border-strong); border-radius:8px; overflow:hidden; }",
    ".cplpw-stagesel button { background: var(--surface-opaque); border:none; border-right:1px solid var(--border); padding:6px 13px; font-size:.78rem; font-weight:600; color: var(--text-body); cursor:pointer; font-family:inherit; }",
    ".cplpw-stagesel button:last-child { border-right:none; }",
    ".cplpw-stagesel button.on.draft { background: var(--mustard-fill); color: var(--text-strong); }",
    ".cplpw-stagesel button.on.active { background: var(--hunter, var(--green-progress)); color: var(--surface-opaque); }",
    ".cplpw-stagesel button.on.tabled { background: var(--surface-muted); color: var(--text-strong); }",
    ".cplpw-pdfbtn { margin-left:auto; background: var(--seal-blue, var(--navy-primary)); color: var(--surface-opaque); border:none; border-radius:8px; padding:7px 14px; font-weight:600; font-size:.8rem; cursor:pointer; font-family:inherit; }",
    ".cplpw-pdfbtn:hover { opacity:.92; }",
    /* The BIG status banner */
    ".cplpw-stagebanner { display:flex; align-items:center; gap:14px; border-radius:10px; padding:12px 18px; margin: 8px 0 12px; }",
    ".cplpw-stagebanner .glyph { font-size:1.5rem; line-height:1; }",
    ".cplpw-stagebanner .big { font-size:1.18rem; font-weight:800; letter-spacing:.16em; }",
    ".cplpw-stagebanner .note { font-size:.8rem; margin-top:2px; opacity:.92; }",
    ".cplpw-stagebanner.draft { background: var(--mustard-fill); color: var(--text-strong); }",
    ".cplpw-stagebanner.active { background: var(--hunter, var(--green-progress)); color: var(--surface-opaque); }",
    ".cplpw-stagebanner.tabled { background: var(--surface-muted); color: var(--text-muted); border:1px solid var(--border-strong); }",
    ".cplpw-chip.stage-draft { background: var(--mustard-fill); color: var(--text-strong); border-color: transparent; font-weight:700; }",
    ".cplpw-chip.stage-active { background: var(--hunter, var(--green-progress)); color: var(--surface-opaque); border-color: transparent; font-weight:700; }",
    ".cplpw-chip.stage-tabled { background: var(--surface-muted); color: var(--text-muted); font-weight:700; }",
    ".cplpw-progrow { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin: 14px 0 4px; }",
    ".cplpw-progbtn { background: var(--surface-opaque); border:1px solid var(--border-strong); border-radius:18px; padding:6px 14px; font-size:.82rem; font-weight:600; color: var(--text-body); cursor:pointer; }",
    ".cplpw-progbtn.on { background: var(--seal-blue, var(--navy-primary)); color: var(--surface-opaque); border-color: transparent; }",
    ".cplpw-hero { background: var(--surface-opaque); border:1px solid var(--border); border-radius:12px; padding:18px 20px 16px; margin: 10px 0 14px; }",
    ".cplpw-hero .college { font-size:.82rem; font-weight:700; letter-spacing:.06em; text-transform:uppercase; color: var(--text-muted); }",
    ".cplpw-hero h2 { margin:2px 0 4px; color: var(--text-strong); font-size:1.5rem; line-height:1.2; }",
    ".cplpw-hero .meta { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin: 6px 0 2px; }",
    ".cplpw-chip { display:inline-block; border-radius:10px; font-size:.7rem; font-weight:600; padding:2px 8px; border:1px solid var(--border-strong); color: var(--text-body); background: var(--surface-subtle); }",
    ".cplpw-chip.start { background: var(--mustard-fill); color: var(--text-strong); border-color: transparent; }",
    ".cplpw-hero .blurb { margin: 8px 0 0; color: var(--text-body); font-size:.9rem; max-width: 860px; }",
    ".cplpw-hero .facts { display:flex; flex-wrap:wrap; gap:6px 14px; margin-top:10px; }",
    ".cplpw-fact { font-size:.76rem; color: var(--text-muted); }",
    ".cplpw-fact::before { content:\"▪ \"; color: var(--mustard-text, var(--yellow-warning)); }",
    /* Stat tiles */
    ".cplpw-tiles { display:grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap:10px; margin: 12px 0; }",
    ".cplpw-tile { background: var(--surface-opaque); border:1px solid var(--border); border-radius:10px; padding:12px 14px; }",
    ".cplpw-tile .n { font-size:1.65rem; font-weight:800; line-height:1.1; color: var(--text-strong); }",
    ".cplpw-tile .n .u { font-size:.9rem; font-weight:600; color: var(--text-muted); margin-left:3px; }",
    ".cplpw-tile .l { font-size:.76rem; color: var(--text-muted); margin-top:3px; line-height:1.3; }",
    ".cplpw-tile.cpl .n { color: var(--hunter, var(--green-progress)); }",
    ".cplpw-tile.clep .n { color: var(--cobalt, var(--accent-link)); }",
    /* Unit meter */
    ".cplpw-meter { margin: 6px 0 4px; }",
    ".cplpw-meter .bar { display:flex; gap:2px; height:26px; border-radius:6px; overflow:hidden; background: var(--surface-muted); }",
    ".cplpw-meter .seg { min-width:0; display:flex; align-items:center; justify-content:center; font-size:.72rem; font-weight:700; color: var(--surface-opaque); white-space:nowrap; overflow:hidden; }",
    ".cplpw-meter .seg.cpl { background: var(--hunter, var(--green-progress)); }",
    ".cplpw-meter .seg.clep { background: var(--cobalt, var(--accent-link)); }",
    ".cplpw-meter .seg.rest { background: var(--surface-muted); color: var(--text-muted); }",
    ".cplpw-legend { display:flex; flex-wrap:wrap; gap:14px; margin: 8px 0 2px; font-size:.78rem; color: var(--text-muted); }",
    ".cplpw-legend .k { display:inline-flex; align-items:center; gap:5px; }",
    ".cplpw-glyph { font-weight:800; }",
    ".cplpw-glyph.cpl { color: var(--hunter, var(--green-progress)); }",
    ".cplpw-glyph.clep { color: var(--cobalt, var(--accent-link)); }",
    ".cplpw-glyph.rest { color: var(--text-faint); }",
    ".cplpw-glyph.adopt { color: var(--violet); }",
    /* Section cards */
    ".cplpw-sections { display:grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap:12px; margin: 12px 0; align-items:start; }",
    ".cplpw-sec { background: var(--surface-opaque); border:1px solid var(--border); border-radius:10px; overflow:hidden; }",
    ".cplpw-sec.wide { grid-column: 1 / -1; }",
    ".cplpw-sec-head { padding:10px 14px 8px; border-bottom:1px solid var(--border); background: var(--surface-subtle); }",
    ".cplpw-sec-head .t { font-weight:700; color: var(--text-strong); font-size:.92rem; }",
    ".cplpw-sec-head .s { font-size:.75rem; color: var(--text-muted); margin-top:2px; }",
    ".cplpw-sec-head .sum { float:right; font-size:.75rem; font-weight:700; }",
    ".cplpw-sec-head .sum.cpl { color: var(--hunter, var(--green-progress)); }",
    ".cplpw-course { display:flex; align-items:baseline; gap:8px; padding:6px 14px; border-bottom:1px solid var(--border); font-size:.84rem; }",
    ".cplpw-course:last-child { border-bottom:none; }",
    ".cplpw-course.done { background: color-mix(in srgb, var(--hunter, var(--green-progress)) 7%, var(--surface-opaque)); }",
    ".cplpw-course .g { flex:0 0 18px; text-align:center; }",
    ".cplpw-course .code { flex:0 0 92px; font-weight:600; color: var(--text-strong); font-size:.78rem; }",
    ".cplpw-course .t { flex:1 1 auto; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }",
    ".cplpw-course.done .t { }",
    ".cplpw-course .u { flex:0 0 auto; font-size:.76rem; color: var(--text-muted); }",
    ".cplpw-course .how { flex:0 0 auto; font-size:.68rem; font-weight:600; border-radius:8px; padding:1px 7px; }",
    ".cplpw-course .how.cpl { color: var(--hunter, var(--green-progress)); border:1px solid var(--hunter, var(--green-progress)); }",
    ".cplpw-course .how.clep { color: var(--cobalt, var(--accent-link)); border:1px solid var(--cobalt, var(--accent-link)); cursor:pointer; background:none; font-family:inherit; }",
    ".cplpw-clepopts { padding:4px 14px 8px 40px; font-size:.76rem; color: var(--text-body); border-bottom:1px solid var(--border); }",
    ".cplpw-clepopts ul { margin:4px 0 2px; padding-left:16px; }",
    ".cplpw-clepopts li { margin:1px 0; }",
    ".cplpw-course .how.adopt { color: var(--violet); border:1px solid var(--violet); cursor:pointer; background:none; font-family:inherit; }",
    ".cplpw-adoptopts { padding:4px 14px 8px 40px; font-size:.76rem; color: var(--text-body); border-bottom:1px solid var(--border); }",
    ".cplpw-adoptopts .h { font-weight:600; }",
    ".cplpw-adoptopts .cred { margin-top:4px; font-weight:600; color: var(--violet); }",
    ".cplpw-adoptopts ul { margin:2px 0 2px; padding-left:16px; }",
    ".cplpw-adoptopts li { margin:1px 0; }",
    /* ⚡ Quick Adopt intake */
    ".cplpw-qa { margin-top:8px; }",
    ".cplpw-qa .go { background: var(--seal-blue, var(--navy-primary)); color: var(--surface-opaque); border:none; border-radius:6px; padding:5px 12px; font-weight:700; font-size:.74rem; cursor:pointer; font-family:inherit; }",
    ".cplpw-qa .go:hover { opacity:.92; }",
    ".cplpw-qa-form { margin-top:8px; display:grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap:6px; max-width:640px; }",
    ".cplpw-qa-form input, .cplpw-qa-form textarea { padding:6px 9px; border:1px solid var(--border-strong); border-radius:6px; font-size:.78rem; font-family:inherit; background: var(--surface-opaque); color: var(--text-body); }",
    ".cplpw-qa-form textarea { grid-column: 1 / -1; min-height:44px; }",
    ".cplpw-qa-form .row { grid-column: 1 / -1; display:flex; gap:8px; align-items:center; }",
    ".cplpw-qa-note { font-size:.72rem; color: var(--text-muted); grid-column: 1 / -1; }",
    ".cplpw-qa-err { font-size:.74rem; color: var(--crimson, var(--red-alert)); font-weight:600; }",
    ".cplpw-qa-ok { font-size:.78rem; color: var(--hunter, var(--green-progress)); font-weight:700; margin-top:8px; }",
    /* Campaign callout */
    ".cplpw-callout { background: var(--navy-primary); color: var(--paper, var(--surface-opaque)); border-radius:12px; padding:18px 22px; margin: 14px 0; }",
    ".cplpw-callout .k { font-size:.72rem; font-weight:700; letter-spacing:.08em; text-transform:uppercase; color: var(--mustard-on-dark, var(--gold-accent)); }",
    ".cplpw-callout .h { font-size:1.28rem; font-weight:800; margin:4px 0 4px; line-height:1.3; color: var(--surface-opaque); }",
    ".cplpw-callout .s { font-size:.85rem; opacity:.85; }",
    /* Footnotes */
    ".cplpw-foot { font-size:.74rem; color: var(--text-muted); margin: 12px 0 20px; line-height:1.55; }",
    ".cplpw-foot a { color: var(--accent-link); }",
    ".cplpw-note { font-size:.78rem; color: var(--mustard-text, var(--yellow-warning)); margin: 6px 0; }",
    /* Dropdown selector (replaces the per-pathway chip row once the directory lands) */
    ".cplpw-selrow { display:flex; flex-wrap:wrap; gap:8px 12px; align-items:center; margin: 14px 0 4px; }",
    ".cplpw-sellabel { font-size:.82rem; font-weight:700; color: var(--text-muted); }",
    ".cplpw-select { font-family:inherit; font-size:.86rem; font-weight:600; color: var(--text-body); background: var(--surface-opaque); border:1px solid var(--border-strong); border-radius:8px; padding:7px 12px; max-width:100%; min-width:min(340px, 100%); cursor:pointer; }",
    ".cplpw-selcount { font-size:.76rem; color: var(--text-muted); }",
    /* Directory card (the auto-generated per-baccalaureate CPL landscape) */
    ".cplpw-dirtag { display:flex; flex-wrap:wrap; align-items:center; gap:6px 10px; background: var(--surface-subtle); border:1px solid var(--border); border-radius:8px; padding:8px 14px; margin: 8px 0 10px; font-size:.78rem; color: var(--text-muted); }",
    ".cplpw-dirtag b { color: var(--text-strong); }",
    ".cplpw-dirintro { font-size:.86rem; color: var(--text-body); margin: 4px 0 8px; max-width: 900px; }",
    ".cplpw-cohort { display:flex; flex-wrap:wrap; gap:6px; margin-top:4px; }",
    ".cplpw-cohort .peer { font-size:.74rem; border:1px solid var(--border); border-radius:10px; padding:2px 8px; background: var(--surface-subtle); color: var(--text-body); }",
    ".cplpw-cohort .peer.home { background: var(--hunter,var(--green-progress)); color: var(--surface-opaque); border-color:transparent; font-weight:700; }",
    ".cplpw-cohort .peer.other-status { opacity:.72; }",
    ".cplpw-frontier { background: var(--mustard-fill); color: var(--text-strong); border-radius:10px; padding:12px 16px; margin:4px 0 10px; font-size:.86rem; }",
    ".cplpw-frontier b { font-weight:800; }",
    ".cplpw-course .cred { flex:0 0 auto; font-size:.72rem; color: var(--text-muted); font-style:italic; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:40%; }",
    "@media (max-width: 720px) { .cplpw-course .code { flex-basis:74px; } .cplpw-hero h2 { font-size:1.2rem; } .cplpw-course .cred { display:none; } }",
    "@media print { .cplpw-progrow, .cplpw-selrow { display:none; } .cplpw-sec { break-inside: avoid; } }",
  ].join("\n");

  function ensureCss() {
    if (document.getElementById(CSS_ID)) return;
    var s = document.createElement("style");
    s.id = CSS_ID;
    s.textContent = CSS;
    document.head.appendChild(s);
  }

  // ── PDF extract (print window) ────────────────────────────────────────────
  // The print window is a fresh document with NO :root token block, so var()
  // can't resolve there — this literal-hex block is the sanctioned exception
  // (same rule as canvas fillStyle / SVG presentation attrs: where var() can't
  // reach, use the resolved First Light literals).
  var PRINT_TOKENS = ":root { --paper:#F4F2ED; --text-strong:#1C1C1A; --text-body:#3A3A36; --text-muted:#5C5C55; --text-faint:#87877F; --surface-opaque:#FFFFFF; --surface-subtle:#F7F5F1; --surface-muted:#ECE9E2; --border:rgba(28,28,26,.14); --border-strong:rgba(28,28,26,.30); --cobalt:#0047AB; --accent-link:#0047AB; --crimson:#920000; --hunter:#2C601A; --green-progress:#2C601A; --violet:#6D28D9; --mustard-fill:#E3B341; --mustard-text:#8B6800; --yellow-warning:#8B6800; --mustard-on-dark:#E3B341; --gold-accent:#E3B341; --navy-primary:#1C1C1A; --seal-blue:#0b3d61; }";
  var PRINT_CSS = [
    "@page { margin: 12mm; }",
    "body { margin: 0; padding: 10px 14px; background: var(--surface-opaque); color: var(--text-body); font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif; -webkit-print-color-adjust: exact; print-color-adjust: exact; }",
    ".cplpw { max-width: none; }",
    ".cplpw-stagebanner, .cplpw-tile, .cplpw-sec, .cplpw-callout { break-inside: avoid; }",
    ".cplpw-course .how.clep { cursor: default; }",
  ].join("\n");

  function exportPdf(container, prog, stagedef) {
    var w = window.open("", "_blank");
    if (!w || !w.document) return; // pop-up blocked — the button title says to allow pop-ups
    var d = w.document;
    d.title = (prog.college ? prog.college + " — " : "") + (prog.program || "CPL Pathway")
      + " (" + stagedef.label + ")";
    var st = d.createElement("style");
    st.textContent = PRINT_TOKENS + "\n" + CSS + "\n" + PRINT_CSS;
    d.head.appendChild(st);
    var clone = container.cloneNode(true);
    Array.prototype.forEach.call(clone.querySelectorAll(".cplpw-toolbar, .cplpw-progrow"), function (n) {
      n.parentNode.removeChild(n);
    });
    // A handout should show the CLEP exam lists that are click-to-expand on screen.
    Array.prototype.forEach.call(clone.querySelectorAll(".cplpw-clepopts"), function (n) {
      n.style.display = "";
    });
    var wrap = d.createElement("div");
    wrap.className = "cplpw";
    while (clone.firstChild) wrap.appendChild(clone.firstChild);
    d.body.appendChild(d.adoptNode ? d.adoptNode(wrap) : wrap);
    if (typeof w.focus === "function") w.focus();
    // Give the new window a beat to lay out before the print dialog opens.
    if (typeof w.setTimeout === "function") w.setTimeout(function () { w.print(); }, 300);
    else w.print();
  }

  // ── DOM helper — createElement/textContent only (no innerHTML with data) ──
  function el(tag, cls, kids) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (kids != null) {
      if (!Array.isArray(kids)) kids = [kids];
      kids.forEach(function (c) {
        if (c == null) return;
        if (typeof c === "string") n.appendChild(document.createTextNode(c));
        else n.appendChild(c);
      });
    }
    return n;
  }
  function clearNode(n) { while (n.firstChild) n.removeChild(n.firstChild); }
  function fmtU(u) {
    if (u == null || isNaN(u)) return "—";
    var s = (Math.round(u * 10) / 10).toString();
    return s;
  }

  // ── Live CER cross-check ──────────────────────────────────────────────────
  // Normalize a course number so catalog spellings match MAP entry drift
  // ("40.5" vs "40.50"). Non-numeric course numbers pass through uppercased.
  function normNum(num) {
    var f = parseFloat(num);
    if (!isNaN(f) && /^[\d.]+$/.test(String(num).trim())) return f.toFixed(2);
    return String(num == null ? "" : num).trim().toUpperCase();
  }
  function courseKey(subj, num) {
    return String(subj == null ? "" : subj).trim().toUpperCase() + " " + normNum(num);
  }
  // Split a "SUBJ NUM" course code from the pathway definition.
  function splitCode(code) {
    var s = String(code == null ? "" : code).trim();
    var i = s.lastIndexOf(" ");
    if (i < 0) return null;
    return { subj: s.slice(0, i), num: s.slice(i + 1) };
  }

  // Build the live lookup indexes from the CER payload:
  //  artIdx:  "SUBJ N.NN" (per college) -> {credential, units, cpl_types}
  //  clepByArea: GE-area name -> [{exam, units, ut}] (system exam-credit chart)
  //  credIdx: unified-title (lowercased) -> every articulation line ANYWHERE
  //           (college + course + units) — feeds the ⊕ adoption-option chips
  //  discIdx: identity discipline -> [unified titles] articulated in it
  function buildLiveIndexes(payload, collegeName) {
    var artIdx = {};
    var clepByArea = {};
    var credIdx = {};
    var discIdx = {};
    if (!payload || !Array.isArray(payload.unified_titles)) return null;
    payload.unified_titles.forEach(function (u) {
      var ut = u && u.ut != null ? String(u.ut) : "";
      (u.articulations || []).forEach(function (a) {
        (a && a.local || []).forEach(function (loc) {
          if (!loc) return;
          var colleges = loc.colleges || [];
          // Every line enters the adoption index (per college).
          colleges.forEach(function (cn) {
            var k = ut.toLowerCase();
            if (!credIdx[k]) credIdx[k] = { ut: ut, lines: [] };
            credIdx[k].lines.push({
              college: String(cn),
              code: (loc.subj != null ? String(loc.subj) : "") + " " + (loc.num != null ? String(loc.num) : ""),
              title: loc.t != null ? String(loc.t) : "",
              units: (typeof loc.u === "number") ? loc.u : null,
            });
          });
          var disc = a.disc != null ? String(a.disc) : "";
          if (disc) {
            if (!discIdx[disc]) discIdx[disc] = [];
            if (discIdx[disc].indexOf(ut) === -1) discIdx[disc].push(ut);
          }
          var hit = colleges.some(function (c) {
            return String(c).toUpperCase().indexOf(String(collegeName).toUpperCase()) !== -1;
          });
          if (!hit) return;
          var key = courseKey(loc.subj, loc.num);
          if (!artIdx[key]) {
            artIdx[key] = {
              credential: ut,
              units: (typeof loc.u === "number") ? loc.u : null,
              cpl_types: u.cpl_types || [],
              local_title: loc.t != null ? String(loc.t) : "",
            };
          }
        });
      });
      // CLEP GE options come from the systemwide exam-credit chart baked into
      // the CER rows (kb/reference/ccc_ge_exam_credit.json, ESLEI 24-35).
      var ge = u.ge_credit;
      if (ge && ge.program === "CLEP" && !ge.na && Array.isArray(ge.areas)) {
        ge.areas.forEach(function (area) {
          if (!clepByArea[area]) clepByArea[area] = [];
          // De-dupe on exam name (CER carries a few spelling-variant rows).
          var exists = clepByArea[area].some(function (e) { return e.exam === ge.exam; });
          if (!exists) clepByArea[area].push({ exam: ge.exam, units: ge.units, ut: ut });
        });
      }
    });
    Object.keys(clepByArea).forEach(function (k) {
      clepByArea[k].sort(function (a, b) { return a.exam < b.exam ? -1 : 1; });
    });
    return { artIdx: artIdx, clepByArea: clepByArea, credIdx: credIdx, discIdx: discIdx,
             college: String(collegeName || ""), generatedAt: payload._generated_at || null };
  }

  // ⊕ Adoption options — for a course the pathway college has NOT articulated,
  // surface where OTHER colleges already articulate the named credentials (or
  // any credential in the named identity discipline): the "someone already did
  // this — adopt it" chip. Purely live-derived; no baked fallback.
  function collectAdoptOptions(adopt, live) {
    if (!adopt || !live || !live.credIdx) return null;
    var wanted = [];
    (adopt.credentials || []).forEach(function (name) {
      var hit = live.credIdx[String(name).toLowerCase()];
      if (hit) wanted.push(hit);
    });
    if (adopt.disc && live.discIdx[adopt.disc]) {
      live.discIdx[adopt.disc].forEach(function (ut) {
        var hit = live.credIdx[ut.toLowerCase()];
        if (hit && wanted.indexOf(hit) === -1) wanted.push(hit);
      });
    }
    var homeUC = live.college.toUpperCase();
    var out = [];
    wanted.forEach(function (cred) {
      var lines = cred.lines.filter(function (l) {
        return l.college.toUpperCase().indexOf(homeUC) === -1;
      });
      if (lines.length) out.push({ credential: cred.ut, lines: lines });
    });
    return out.length ? out : null;
  }

  // ── Directory tier (auto-generated per-baccalaureate cards) ───────────────
  // The featured index (buildLiveIndexes) is scoped to ONE college; the
  // directory needs every college's CPL keyed by TOP family, so it gets its
  // own global index over the same CER payload. Two lookups:
  //   byCollegeTop4: NORMCOLLEGE -> top4 -> {key -> {ut, code, title, units, cpl_types}}
  //     — a college's own CPL articulations in a field (the ✓ list).
  //   byTop4:        top4 -> {ut -> {ut, cpl_types, colleges:{key -> line}}}
  //     — every college's CPL in a field, grouped by credential (the ⊕ pool).
  //   byCollegeCount: NORMCOLLEGE -> {ut:true} (distinct CPL credentials, all fields).
  //   clepByArea:    GE-area -> exams (systemwide CLEP chart; reused from featured).
  function normCollege(c) { return String(c == null ? "" : c).trim().toUpperCase(); }
  function buildDirectoryIndex(payload) {
    if (!payload || !Array.isArray(payload.unified_titles)) return null;
    var byCollegeTop4 = {}, byTop4 = {}, byCollegeCount = {}, clepByArea = {};
    payload.unified_titles.forEach(function (u) {
      var ut = u && u.ut != null ? String(u.ut) : "";
      (u.articulations || []).forEach(function (a) {
        var top4 = String((a && a.top) || "").slice(0, 4);
        (a && a.local || []).forEach(function (loc) {
          if (!loc) return;
          var code = (loc.subj != null ? String(loc.subj) : "") + " " + (loc.num != null ? String(loc.num) : "");
          var units = (typeof loc.u === "number") ? loc.u : null;
          var title = loc.t != null ? String(loc.t) : "";
          (loc.colleges || []).forEach(function (cn) {
            var nc = normCollege(cn);
            if (!nc) return;
            if (!byCollegeCount[nc]) byCollegeCount[nc] = {};
            byCollegeCount[nc][ut] = true;
            if (!top4) return;
            if (!byCollegeTop4[nc]) byCollegeTop4[nc] = {};
            if (!byCollegeTop4[nc][top4]) byCollegeTop4[nc][top4] = {};
            var mk = ut + "||" + code;
            if (!byCollegeTop4[nc][top4][mk]) {
              byCollegeTop4[nc][top4][mk] = { ut: ut, code: code, title: title, units: units, cpl_types: u.cpl_types || [] };
            }
            if (!byTop4[top4]) byTop4[top4] = {};
            if (!byTop4[top4][ut]) byTop4[top4][ut] = { ut: ut, cpl_types: u.cpl_types || [], colleges: {} };
            var ck = nc + "||" + code;
            if (!byTop4[top4][ut].colleges[ck]) {
              byTop4[top4][ut].colleges[ck] = { college: String(cn), code: code, title: title, units: units };
            }
          });
        });
      });
      var ge = u.ge_credit;
      if (ge && ge.program === "CLEP" && !ge.na && Array.isArray(ge.areas)) {
        ge.areas.forEach(function (area) {
          if (!clepByArea[area]) clepByArea[area] = [];
          if (!clepByArea[area].some(function (e) { return e.exam === ge.exam; })) {
            clepByArea[area].push({ exam: ge.exam, units: ge.units, ut: ut });
          }
        });
      }
    });
    return { byCollegeTop4: byCollegeTop4, byTop4: byTop4, byCollegeCount: byCollegeCount,
             clepByArea: clepByArea, generatedAt: payload._generated_at || null };
  }

  // Resolve a directory program against the directory index: the college's own
  // in-field CPL (✓), the peer-college adoption pool (⊕, home-college excluded
  // and credentials the home college already has removed — those aren't gaps),
  // the same-field baccalaureate cohort, and the roll-up counts.
  function resolveDirectory(prog, dir, allPrograms) {
    var nc = prog.cer_college ? normCollege(prog.cer_college) : null;
    var top4 = prog.top4 || "";
    var mine = [];
    if (nc && dir && dir.byCollegeTop4[nc] && dir.byCollegeTop4[nc][top4]) {
      var mm = dir.byCollegeTop4[nc][top4];
      mine = Object.keys(mm).map(function (k) { return mm[k]; });
      mine.sort(function (a, b) { return a.code < b.code ? -1 : (a.code > b.code ? 1 : 0); });
    }
    var mineUts = {};
    mine.forEach(function (m) { mineUts[m.ut.toLowerCase()] = true; });
    var pool = [];
    if (dir && dir.byTop4[top4]) {
      Object.keys(dir.byTop4[top4]).forEach(function (ut) {
        if (mineUts[ut.toLowerCase()]) return; // already at this college — not an adoption gap
        var cred = dir.byTop4[top4][ut];
        var lines = Object.keys(cred.colleges).map(function (k) { return cred.colleges[k]; })
          .filter(function (l) { return !nc || normCollege(l.college) !== nc; });
        if (!lines.length) return;
        lines.sort(function (a, b) { return a.college < b.college ? -1 : 1; });
        var cset = {};
        lines.forEach(function (l) { cset[normCollege(l.college)] = true; });
        pool.push({ credential: cred.ut, cpl_types: cred.cpl_types, lines: lines, colleges: Object.keys(cset).length });
      });
      pool.sort(function (a, b) { return b.colleges - a.colleges || (a.credential < b.credential ? -1 : 1); });
    }
    var cohort = (allPrograms || []).filter(function (p) { return p.top4 === top4; });
    var poolColleges = {};
    pool.forEach(function (pc) { pc.lines.forEach(function (l) { poolColleges[normCollege(l.college)] = true; }); });
    return {
      mine: mine, pool: pool, cohort: cohort,
      mineCreds: Object.keys(mineUts).length,
      mineCourses: mine.length,
      poolCreds: pool.length,
      poolColleges: Object.keys(poolColleges).length,
      totalAtCollege: (nc && dir && dir.byCollegeCount[nc]) ? Object.keys(dir.byCollegeCount[nc]).length : 0,
      clepExams: dir ? countClepExams(dir.clepByArea) : 0,
      top4: top4,
    };
  }
  function countClepExams(clepByArea) {
    var seen = {};
    Object.keys(clepByArea || {}).forEach(function (area) {
      (clepByArea[area] || []).forEach(function (e) { seen[e.exam] = true; });
    });
    return Object.keys(seen).length;
  }

  // ── Pathway resolution ────────────────────────────────────────────────────
  // Walk the pathway definition and resolve each course/slot against the live
  // indexes (or the baked fallback when live is null). Returns the resolved
  // model the renderer consumes, including the unit buckets.
  function resolvePathway(prog, live) {
    var cplUnits = 0, clepUnits = 0, totalListed = 0;
    var sections = (prog.sections || []).map(function (sec) {
      var rows = (sec.courses || []).map(function (c) {
        var row = {
          code: c.code || null,
          title: c.title || "",
          units: (typeof c.units === "number") ? c.units : null,
          status: "rest",       // rest | cpl | clep
          how: null,            // chip text
          detail: null,         // hover title
          clepOptions: null,    // [{exam, units}]
        };
        // 1) Apprenticeship CPL — live match against the college's MAP
        //    articulations, falling back to the baked `cpl` stamp.
        var m = null;
        if (row.code && live) {
          var p = splitCode(row.code);
          if (p) m = live.artIdx[courseKey(p.subj, p.num)] || null;
        }
        if (!m && c.cpl && c.cpl.credential) {
          // Baked stamp — either the fallback for a live-match miss, or CPL a
          // college awards outside MAP (c.cpl.source names where it's granted,
          // e.g. "Awarded by the college per its catalog").
          m = { credential: c.cpl.credential, units: row.units, cpl_types: c.cpl.types || [],
                local_title: row.title, source: c.cpl.source || null };
        }
        if (m) {
          row.status = "cpl";
          var viaTypes = (m.cpl_types && m.cpl_types.length) ? m.cpl_types.join(", ") : "CPL";
          row.how = "✓ CPL";
          row.detail = (m.source || "Articulated in the MAP platform") + ": “" + m.credential + "” → " + (row.code || row.title) + " (" + viaTypes + ")";
          if (typeof m.units === "number" && row.units == null) row.units = m.units;
        }
        // 2) CLEP option — GE slots declare a `clep_area`; qualifying exams
        //    come from the live chart (fallback: baked count).
        if (row.status !== "cpl" && c.clep_area) {
          var opts = (live && live.clepByArea[c.clep_area]) || c.clep_fallback || [];
          if (opts.length) {
            row.status = "clep";
            row.clepOptions = opts;
            row.how = "◆ CLEP × " + opts.length;
            row.detail = opts.length + " CLEP exam(s) carry systemwide GE credit in “" + c.clep_area + "” (ESLEI 24-35)";
          }
        }
        // 3) ⊕ Adoption option — this college hasn't articulated the course,
        //    but other colleges articulate the named credential(s)/discipline.
        //    Doesn't change status or units — it's an opportunity, not credit.
        if (row.status !== "cpl" && c.adopt) {
          var adoptions = collectAdoptOptions(c.adopt, live);
          if (adoptions) {
            row.adoptOptions = adoptions;
            row.adoptNote = c.adopt.note || null;
          }
        }
        // `no_count` sections (e.g. alternate-track course lists) render and
        // live-resolve, but never enter the unit buckets — a student takes ONE
        // track, so counting both would overstate the CPL number.
        if (typeof row.units === "number" && !sec.no_count) {
          totalListed += row.units;
          if (row.status === "cpl") cplUnits += row.units;
          else if (row.status === "clep") clepUnits += row.units;
        }
        return row;
      });
      var secCpl = rows.reduce(function (s, r) { return s + (r.status === "cpl" && r.units ? r.units : 0); }, 0);
      var secAll = rows.reduce(function (s, r) { return s + (r.units || 0); }, 0);
      return { def: sec, rows: rows, cplUnits: secCpl, allUnits: secAll };
    });
    var total = (typeof prog.total_units === "number") ? prog.total_units : totalListed;
    var hasAdopt = sections.some(function (s) {
      return s.rows.some(function (r) { return !!r.adoptOptions; });
    });
    return {
      sections: sections,
      cplUnits: Math.round(cplUnits * 10) / 10,
      clepUnits: Math.round(clepUnits * 10) / 10,
      totalUnits: total,
      restUnits: Math.max(0, Math.round((total - cplUnits - clepUnits) * 10) / 10),
      hasAdopt: hasAdopt,
    };
  }

  // ── Renderers ─────────────────────────────────────────────────────────────
  function renderMeter(model) {
    var wrap = el("div", "cplpw-meter");
    var bar = el("div", "bar");
    var total = model.totalUnits || 1;
    [["cpl", model.cplUnits, "✓ " + fmtU(model.cplUnits) + "u CPL"],
     ["clep", model.clepUnits, "◆ " + fmtU(model.clepUnits) + "u CLEP-eligible"],
     ["rest", model.restUnits, fmtU(model.restUnits) + "u in class"]].forEach(function (t) {
      if (!t[1]) return;
      var seg = el("div", "seg " + t[0], t[2]);
      seg.style.flexGrow = String(t[1]);
      seg.style.flexBasis = "0";
      seg.title = t[2] + " of " + fmtU(total) + " total units";
      bar.appendChild(seg);
    });
    wrap.appendChild(bar);
    var legend = el("div", "cplpw-legend", [
      el("span", "k", [el("span", "cplpw-glyph cpl", "✓"), " CPL already articulated by this college in the MAP platform"]),
      el("span", "k", [el("span", "cplpw-glyph clep", "◆"), " GE requirement a CLEP exam can satisfy (systemwide chart; college applies it)"]),
      el("span", "k", [el("span", "cplpw-glyph rest", "○"), " remaining classroom coursework"]),
    ]);
    if (model.hasAdopt) {
      legend.appendChild(el("span", "k", [el("span", "cplpw-glyph adopt", "⊕"),
        " articulated at ANOTHER college — an adoption opportunity here"]));
    }
    wrap.appendChild(legend);
    return wrap;
  }

  function renderTiles(model, prog) {
    var tiles = el("div", "cplpw-tiles");
    var unitWord = prog.unit_system === "quarter" ? "qtr units" : "units";
    function tile(cls, num, unit, label) {
      var t = el("div", "cplpw-tile" + (cls ? " " + cls : ""));
      var n = el("div", "n", num);
      if (unit) n.appendChild(el("span", "u", unit));
      t.appendChild(n);
      t.appendChild(el("div", "l", label));
      return t;
    }
    tiles.appendChild(tile("cpl", "✓ " + fmtU(model.cplUnits), unitWord, prog.cpl_tile_label || "CPL on day one — prior-learning credit already articulated in MAP"));
    tiles.appendChild(tile("clep", "◆ " + fmtU(model.clepUnits), unitWord, "more GE units available by CLEP exam — no classroom seat time"));
    tiles.appendChild(tile(null, fmtU(model.totalUnits), unitWord, prog.total_tile_label || ("total for the " + (prog.degree || "degree"))));
    var pct = model.totalUnits ? Math.round(((model.cplUnits + model.clepUnits) / model.totalUnits) * 100) : 0;
    tiles.appendChild(tile(null, pct + "%", null, "of the degree reachable without repeating training you already have"));
    return tiles;
  }

  function renderSection(secModel, prog) {
    var isQuarter = prog && prog.unit_system === "quarter";
    var sec = el("div", "cplpw-sec" + (secModel.def.wide ? " wide" : ""));
    var head = el("div", "cplpw-sec-head");
    if (secModel.cplUnits > 0) {
      head.appendChild(el("span", "sum cpl", "✓ " + fmtU(secModel.cplUnits) + " / " + fmtU(secModel.allUnits) + "u by CPL"));
    } else if (secModel.allUnits > 0) {
      head.appendChild(el("span", "sum", fmtU(secModel.allUnits) + "u"));
    }
    head.appendChild(el("div", "t", secModel.def.title || ""));
    if (secModel.def.note) head.appendChild(el("div", "s", secModel.def.note));
    sec.appendChild(head);
    secModel.rows.forEach(function (r) {
      var row = el("div", "cplpw-course" + (r.status === "cpl" ? " done" : ""));
      var glyph = r.status === "cpl" ? "✓" : (r.status === "clep" ? "◆" : "○");
      row.appendChild(el("span", "g cplpw-glyph " + (r.status === "cpl" ? "cpl" : r.status === "clep" ? "clep" : "rest"), glyph));
      if (r.code) row.appendChild(el("span", "code", r.code));
      var t = el("span", "t", r.title);
      t.title = r.detail || r.title;
      row.appendChild(t);
      if (r.units != null) row.appendChild(el("span", "u", fmtU(r.units) + "u"));
      if (r.status === "cpl") {
        var chip = el("span", "how cpl", r.how);
        chip.title = r.detail || "";
        row.appendChild(chip);
      }
      var adoptPanel = null;
      if (r.adoptOptions) {
        var nCred = r.adoptOptions.length;
        var abtn = document.createElement("button");
        abtn.className = "how adopt";
        abtn.type = "button";
        abtn.textContent = "⊕ adopted elsewhere × " + nCred;
        abtn.title = nCred + " credential(s) already articulated to equivalent coursework at other colleges — an adoption opportunity for this college. Click to list.";
        abtn.setAttribute("aria-expanded", "false");
        abtn.addEventListener("click", function () {
          var open = adoptPanel.style.display !== "none";
          adoptPanel.style.display = open ? "none" : "";
          abtn.setAttribute("aria-expanded", open ? "false" : "true");
        });
        row.appendChild(abtn);
        adoptPanel = el("div", "cplpw-adoptopts");
        adoptPanel.style.display = "none";
        adoptPanel.appendChild(el("div", "h",
          "Already articulated at other colleges — CPL this college could adopt" +
          (r.adoptNote ? " (" + r.adoptNote + ")" : "") + ":"));
        r.adoptOptions.forEach(function (o) {
          var ul = el("ul");
          o.lines.forEach(function (l) {
            ul.appendChild(el("li", null, l.college + ": " + l.code + " — " + l.title +
              (l.units != null ? " (" + fmtU(l.units) + "u)" : "")));
          });
          adoptPanel.appendChild(el("div", "cred", "⊕ " + o.credential));
          adoptPanel.appendChild(ul);
        });
        adoptPanel.appendChild(buildQuickAdopt(prog, r));
      }
      var optsPanel = null;
      if (r.status === "clep" && r.clepOptions) {
        var btn = document.createElement("button");
        btn.className = "how clep";
        btn.type = "button";
        btn.textContent = r.how;
        btn.title = (r.detail || "") + " — click to list the exams";
        btn.setAttribute("aria-expanded", "false");
        btn.addEventListener("click", function () {
          var open = optsPanel.style.display !== "none";
          optsPanel.style.display = open ? "none" : "";
          btn.setAttribute("aria-expanded", open ? "false" : "true");
        });
        row.appendChild(btn);
        optsPanel = el("div", "cplpw-clepopts");
        optsPanel.style.display = "none";
        optsPanel.appendChild(el("div", null, "CLEP exams carrying systemwide GE credit here (min " +
          (isQuarter ? "4 quarter units each" : "3 semester units each") +
          "; passing score 50 — ESLEI 24-35):"));
        var ul = el("ul");
        r.clepOptions.forEach(function (o) {
          // The chart's per-exam minimums are semester-grained; on a quarter
          // campus show just the exam names (the header carries the minimum).
          ul.appendChild(el("li", null, o.exam +
            (!isQuarter && o.units ? " — " + fmtU(o.units) + "u" : "")));
        });
        optsPanel.appendChild(ul);
      }
      sec.appendChild(row);
      if (adoptPanel) sec.appendChild(adoptPanel);
      if (optsPanel) sec.appendChild(optsPanel);
    });
    return sec;
  }

  function renderProgram(root, prog, live, liveNote) {
    var model = resolvePathway(prog, live);
    var frag = document.createDocumentFragment();

    // Status toolbar — selector (per-browser view override) + PDF extract
    var stage = getStage(prog);
    var stagedef = STAGE_BY_ID[stage] || STAGES[0];
    var bar = el("div", "cplpw-toolbar");
    bar.appendChild(el("span", "lbl", "Status:"));
    var sel = el("div", "cplpw-stagesel");
    sel.setAttribute("role", "radiogroup");
    sel.setAttribute("aria-label", "Pathway status");
    STAGES.forEach(function (s) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = (s.id === stage) ? ("on " + s.cls) : "";
      b.textContent = s.glyph + " " + s.label;
      b.setAttribute("role", "radio");
      b.setAttribute("aria-checked", s.id === stage ? "true" : "false");
      b.title = s.note + " (Changes how this pathway is labeled in THIS browser; the published default is set in cpl_pathways_data.js.)";
      b.addEventListener("click", function () {
        setStage(prog, s.id);
        renderProgram(root, prog, live, liveNote);
      });
      sel.appendChild(b);
    });
    bar.appendChild(sel);
    var pdf = document.createElement("button");
    pdf.type = "button";
    pdf.className = "cplpw-pdfbtn";
    pdf.textContent = "⬇ PDF";
    pdf.title = "Open a print-ready extract of this course map (save as PDF from the print dialog; allow pop-ups)";
    pdf.addEventListener("click", function () { exportPdf(root, prog, stagedef); });
    bar.appendChild(pdf);
    frag.appendChild(bar);

    // The BIG status label
    var banner = el("div", "cplpw-stagebanner " + stagedef.cls);
    banner.appendChild(el("span", "glyph", stagedef.glyph));
    banner.appendChild(el("div", null, [
      el("div", "big", stagedef.big),
      el("div", "note", stagedef.note),
    ]));
    frag.appendChild(banner);

    // Hero
    var hero = el("div", "cplpw-hero");
    hero.appendChild(el("div", "college", prog.college || ""));
    hero.appendChild(el("h2", null, (prog.program || "") + (prog.degree ? " — " + prog.degree : "")));
    var meta = el("div", "meta");
    meta.appendChild(el("span", "cplpw-chip stage-" + stagedef.cls, stagedef.glyph + " " + stagedef.label));
    if (prog.start) meta.appendChild(el("span", "cplpw-chip start", "First cohort: " + prog.start));
    if (prog.status) meta.appendChild(el("span", "cplpw-chip", prog.status));
    if (prog.audience) meta.appendChild(el("span", "cplpw-chip", prog.audience));
    hero.appendChild(meta);
    if (prog.blurb) hero.appendChild(el("p", "blurb", prog.blurb));
    if (prog.facts && prog.facts.length) {
      var facts = el("div", "facts");
      prog.facts.forEach(function (f) { facts.appendChild(el("span", "cplpw-fact", f)); });
      hero.appendChild(facts);
    }
    frag.appendChild(hero);

    if (liveNote) frag.appendChild(el("div", "cplpw-note", liveNote));

    frag.appendChild(renderTiles(model, prog));
    frag.appendChild(renderMeter(model));

    // Section cards
    var grid = el("div", "cplpw-sections");
    model.sections.forEach(function (s) { grid.appendChild(renderSection(s, prog)); });
    frag.appendChild(grid);

    // Campaign callout
    if (prog.campaign && prog.campaign.headline) {
      var co = el("div", "cplpw-callout");
      co.appendChild(el("div", "k", prog.campaign.kicker || "The outreach message"));
      var headline = prog.campaign.headline
        .replace("{cpl_units}", fmtU(model.cplUnits))
        .replace("{combo_units}", fmtU(model.cplUnits + model.clepUnits));
      co.appendChild(el("div", "h", headline));
      if (prog.campaign.sub) co.appendChild(el("div", "s", prog.campaign.sub));
      frag.appendChild(co);
    }

    // Footnotes
    var foot = el("div", "cplpw-foot");
    (prog.footnotes || []).forEach(function (f) { foot.appendChild(el("div", null, "• " + f)); });
    if (live && live.generatedAt) {
      foot.appendChild(el("div", null, "• CPL ✓ marks derive from the live MAP-platform articulation data in this dashboard’s CER dataset (extracted " + String(live.generatedAt).slice(0, 10) + ")."));
    }
    if (prog.sources && prog.sources.length) {
      var srcRow = el("div", null, "Sources: ");
      prog.sources.forEach(function (s, i) {
        if (i) srcRow.appendChild(document.createTextNode(" · "));
        if (s.url) {
          var a = document.createElement("a");
          a.href = s.url; a.target = "_blank"; a.rel = "noopener";
          a.textContent = s.label || s.url;
          srcRow.appendChild(a);
        } else {
          srcRow.appendChild(document.createTextNode(s.label || ""));
        }
      });
      foot.appendChild(srcRow);
    }
    frag.appendChild(foot);

    clearNode(root);
    root.removeAttribute("style");
    root.appendChild(frag);
  }

  // ── Directory card renderer ───────────────────────────────────────────────
  // One auto-generated card per CCC baccalaureate: program metadata (from the
  // COCI export) + a LIVE CPL landscape (the college's own in-field CPL, the
  // peer-college adoption pool with ⚡ Quick Adopt, the same-field cohort, and
  // GE-by-CLEP), all derived from the CER dataset by TOP + college.
  function renderDirectory(root, prog, dir, allPrograms, liveNote) {
    var m = resolveDirectory(prog, dir, allPrograms);
    var frag = document.createDocumentFragment();

    // Directory tag (this is a field-level view — not a course-by-course map)
    var tag = el("div", "cplpw-dirtag");
    tag.appendChild(el("span", null, [document.createTextNode("CPL LANDSCAPE — ")]));
    tag.appendChild(el("b", null, "live from the MAP platform"));
    tag.appendChild(el("span", null,
      "· a field-level view of the prior-learning credit along the associate-to-bachelor's pathway. For a course-by-course map, pick a ★ Featured pathway above."));
    frag.appendChild(tag);

    // Hero
    var hero = el("div", "cplpw-hero");
    hero.appendChild(el("div", "college", prog.college || ""));
    hero.appendChild(el("h2", null, (prog.program || "") + (prog.degree ? " — " + prog.degree : "")));
    var meta = el("div", "meta");
    var statusCls = prog.status === "Active" ? "stage-active" : "start";
    meta.appendChild(el("span", "cplpw-chip " + statusCls, prog.status || "—"));
    if (prog.field) meta.appendChild(el("span", "cplpw-chip", prog.field + (prog.top ? " (TOP " + prog.top + ")" : "")));
    if (prog.units != null) meta.appendChild(el("span", "cplpw-chip", fmtU(prog.units) + " major units"));
    if (prog.degree_abbr) meta.appendChild(el("span", "cplpw-chip", prog.degree_abbr));
    hero.appendChild(meta);
    frag.appendChild(hero);

    if (liveNote) { frag.appendChild(el("div", "cplpw-note", liveNote)); }

    // Stat tiles
    var tiles = el("div", "cplpw-tiles");
    function tile(cls, num, label) {
      var t = el("div", "cplpw-tile" + (cls ? " " + cls : ""));
      t.appendChild(el("div", "n", num));
      t.appendChild(el("div", "l", label));
      return t;
    }
    tiles.appendChild(tile("cpl", "✓ " + m.mineCreds,
      "credential" + (m.mineCreds === 1 ? "" : "s") + " " + (prog.college || "this college") + " already articulates for CPL in this field (" + m.mineCourses + " course" + (m.mineCourses === 1 ? "" : "s") + ")"));
    tiles.appendChild(tile(null, "⊕ " + m.poolCreds,
      "credential" + (m.poolCreds === 1 ? "" : "s") + " peers have articulated that this college could adopt — from " + m.poolColleges + " college" + (m.poolColleges === 1 ? "" : "s")));
    tiles.appendChild(tile(null, String(m.cohort.length),
      "college" + (m.cohort.length === 1 ? "" : "s") + " statewide offer a baccalaureate in this field"));
    tiles.appendChild(tile(null, "◆ " + m.clepExams,
      "CLEP exams carry systemwide GE credit — test out of general education (ESLEI 24-35)"));
    frag.appendChild(tiles);

    // Frontier banner when there's nothing yet in the field
    if (m.mineCreds === 0 && m.poolCreds === 0) {
      frag.appendChild(el("div", "cplpw-frontier",
        [el("b", null, "The CPL frontier. "),
         document.createTextNode("No college has articulated CPL for this field in the MAP platform yet. "
           + "That's the opportunity: this college could be first to recognize the licenses, certifications, "
           + "and industry training its students already hold — and every ⊕ that appears here becomes an adoption "
           + "menu for the other colleges offering this degree.")]));
    }

    // Section: the college's own CPL in the field (✓)
    if (m.mine.length) {
      var s1 = el("div", "cplpw-sec wide");
      var h1 = el("div", "cplpw-sec-head");
      h1.appendChild(el("span", "sum cpl", "✓ " + m.mine.length + " course" + (m.mine.length === 1 ? "" : "s")));
      h1.appendChild(el("div", "t", "CPL " + (prog.college || "this college") + " already articulates in this field"));
      h1.appendChild(el("div", "s", "Prior-learning credit a student in this pathway can claim today — live from the MAP platform."));
      s1.appendChild(h1);
      m.mine.forEach(function (r) {
        var row = el("div", "cplpw-course done");
        row.appendChild(el("span", "g cplpw-glyph cpl", "✓"));
        if (r.code) row.appendChild(el("span", "code", r.code));
        var t = el("span", "t", r.title || r.ut);
        t.title = "“" + r.ut + "” → " + (r.code || r.title) + (r.cpl_types && r.cpl_types.length ? " (" + r.cpl_types.join(", ") + ")" : "");
        row.appendChild(t);
        if (r.ut && r.ut !== r.title) row.appendChild(el("span", "cred", r.ut));
        if (r.units != null) row.appendChild(el("span", "u", fmtU(r.units) + "u"));
        s1.appendChild(row);
      });
      frag.appendChild(s1);
    }

    // Section: adoption opportunities (⊕) — peers' CPL this college could adopt
    if (m.pool.length) {
      var s2 = el("div", "cplpw-sec wide");
      var h2 = el("div", "cplpw-sec-head");
      h2.appendChild(el("span", "sum", m.pool.length + " to adopt"));
      h2.appendChild(el("div", "t", "Adoption opportunities — CPL other colleges have already proven in this field"));
      var capNote = m.pool.length > DIR_POOL_CAP ? " Showing the " + DIR_POOL_CAP + " most widely-adopted first." : "";
      h2.appendChild(el("div", "s", "Each credential below is articulated for CPL at another California college. This college could adopt it — and a student can request it. ⚡ Quick Adopt records the request for the CPL team." + capNote));
      s2.appendChild(h2);
      var moreWrap = el("div");
      moreWrap.style.display = "none";
      m.pool.forEach(function (pc, idx) {
        var row = el("div", "cplpw-course");
        row.appendChild(el("span", "g cplpw-glyph adopt", "⊕"));
        var t = el("span", "t", pc.credential);
        t.title = pc.credential + " — articulated at " + pc.colleges + " college" + (pc.colleges === 1 ? "" : "s");
        row.appendChild(t);
        if (pc.cpl_types && pc.cpl_types.length) row.appendChild(el("span", "cred", pc.cpl_types.join(", ")));
        var abtn = document.createElement("button");
        abtn.className = "how adopt";
        abtn.type = "button";
        abtn.textContent = "⊕ " + pc.colleges + " college" + (pc.colleges === 1 ? "" : "s");
        abtn.setAttribute("aria-expanded", "false");
        var panel = el("div", "cplpw-adoptopts");
        panel.style.display = "none";
        abtn.addEventListener("click", function () {
          var open = panel.style.display !== "none";
          panel.style.display = open ? "none" : "";
          abtn.setAttribute("aria-expanded", open ? "false" : "true");
        });
        row.appendChild(abtn);
        panel.appendChild(el("div", "h", "Already articulated for CPL at:"));
        var ul = el("ul");
        pc.lines.forEach(function (l) {
          ul.appendChild(el("li", null, l.college + ": " + l.code + (l.title ? " — " + l.title : "") +
            (l.units != null ? " (" + fmtU(l.units) + "u)" : "")));
        });
        panel.appendChild(ul);
        panel.appendChild(buildQuickAdopt(prog, {
          code: null, title: pc.credential,
          adoptOptions: [{ credential: pc.credential, lines: pc.lines }],
        }));
        var host = (idx < DIR_POOL_CAP) ? s2 : moreWrap;
        host.appendChild(row);
        host.appendChild(panel);
      });
      if (m.pool.length > DIR_POOL_CAP) {
        var moreBtn = document.createElement("button");
        moreBtn.type = "button";
        moreBtn.className = "cplpw-progbtn";
        moreBtn.style.margin = "8px 14px";
        var hidden = m.pool.length - DIR_POOL_CAP;
        moreBtn.textContent = "＋ Show all " + m.pool.length + " (" + hidden + " more)";
        moreBtn.addEventListener("click", function () {
          var open = moreWrap.style.display !== "none";
          moreWrap.style.display = open ? "none" : "";
          moreBtn.textContent = open ? ("＋ Show all " + m.pool.length + " (" + hidden + " more)") : "− Show fewer";
        });
        s2.appendChild(moreBtn);
        s2.appendChild(moreWrap);
      }
      frag.appendChild(s2);
    }

    // Section: the same-field baccalaureate cohort
    if (m.cohort.length > 1) {
      var s3 = el("div", "cplpw-sec wide");
      var h3 = el("div", "cplpw-sec-head");
      h3.appendChild(el("div", "t", "Colleges offering a baccalaureate in this field"));
      h3.appendChild(el("div", "s", "The peer network — where an adopted articulation travels. CCC baccalaureates accept CCC-transcribed CPL without the transfer restrictions CSU and UC apply."));
      s3.appendChild(h3);
      var cohortWrap = el("div", "cplpw-cohort");
      cohortWrap.style.padding = "10px 14px";
      m.cohort.forEach(function (p) {
        var isHome = prog.cer_college && p.cer_college && normCollege(p.cer_college) === normCollege(prog.cer_college);
        if (!isHome && p.coci_college && prog.coci_college) isHome = p.coci_college === prog.coci_college;
        var cls = "peer" + (isHome ? " home" : "") + (p.status !== "Active" ? " other-status" : "");
        var chip = el("span", cls, p.college + (p.status !== "Active" ? " · " + p.status : ""));
        chip.title = p.college + " — " + p.program + " (" + p.status + ")";
        cohortWrap.appendChild(chip);
      });
      s3.appendChild(cohortWrap);
      frag.appendChild(s3);
    }

    // Footnotes + sources
    var foot = el("div", "cplpw-foot");
    foot.appendChild(el("div", null, "• This card is auto-generated from the CCCCO COCI program export (baccalaureate degrees; snapshot " +
      ((window.CPL_BACCALAUREATES && window.CPL_BACCALAUREATES._as_of) || prog._as_of || "recent") + "). The CPL ✓/⊕ marks derive live from this dashboard's CER dataset (the MAP platform's articulation data)" +
      (dir && dir.generatedAt ? ", extracted " + String(dir.generatedAt).slice(0, 10) : "") + "."));
    foot.appendChild(el("div", null, "• ✓ = the credential is articulated for CPL by " + (prog.college || "this college") +
      " in the field's TOP code (" + (prog.top || prog.top4) + "). ⊕ = another California college articulates it — an adoption opportunity here. " +
      (prog.cer_college ? "" : "This college has no CPL articulations in the MAP platform yet, so only the field-wide adoption pool is shown.")));
    foot.appendChild(el("div", null, "• Why baccalaureate pathways: CCC baccalaureate degrees accept CPL that the community colleges transcribe with none of the restrictions CSU and UC place on incoming CPL — so a counselor can recommend a student accept eligible CPL with confidence it won't cost them transfer options."));
    var srcRow = el("div", null, "Sources: ");
    [{ label: "CCC Baccalaureate Degree Programs (CCCCO)", url: "https://www.cccco.edu/About-Us/Chancellors-Office/Divisions/Educational-Services-and-Support/What-we-do/Curriculum-and-Instruction-Unit/Curriculum/Baccalaureate-Degree-Program" },
     { label: "Find a bachelor's degree (I Can Go To College)", url: "https://icangotocollege.com/bachelors-degree" },
     { label: "MAP CPL Insights Dashboard", url: "https://cpldashboardcccco.azurewebsites.net/insights/dashboard" }].forEach(function (s, i) {
      if (i) srcRow.appendChild(document.createTextNode(" · "));
      var a = document.createElement("a");
      a.href = s.url; a.target = "_blank"; a.rel = "noopener"; a.textContent = s.label;
      srcRow.appendChild(a);
    });
    foot.appendChild(srcRow);
    frag.appendChild(foot);

    clearNode(root);
    root.removeAttribute("style");
    root.appendChild(frag);
  }

  // ── Dropdown selector (featured + field-grouped directory) ────────────────
  function buildSelector(items, directory, onChange) {
    var row = el("div", "cplpw-selrow");
    var sel = document.createElement("select");
    sel.className = "cplpw-select";
    sel.setAttribute("aria-label", "Choose a pathway");
    function option(val, text) {
      var o = document.createElement("option");
      o.value = String(val);
      o.textContent = text;
      return o;
    }
    // Featured group
    var fg = document.createElement("optgroup");
    fg.label = "★ Featured — full course maps";
    items.forEach(function (it, i) {
      if (it.kind === "featured") fg.appendChild(option(i, (it.prog.college ? it.prog.college + " — " : "") + (it.prog.program || ("Program " + (i + 1)))));
    });
    if (fg.children.length) sel.appendChild(fg);
    // Directory groups, by field (preserve the data-file order)
    var fields = [], seen = {};
    directory.forEach(function (p) { if (!seen[p.field]) { seen[p.field] = true; fields.push(p.field); } });
    fields.forEach(function (f) {
      var og = document.createElement("optgroup");
      og.label = f;
      items.forEach(function (it, i) {
        if (it.kind === "directory" && it.prog.field === f) {
          var st = (it.prog.status && it.prog.status !== "Active") ? " (" + it.prog.status + ")" : "";
          og.appendChild(option(i, (it.prog.college || "") + " — " + (it.prog.program || "") + st));
        }
      });
      if (og.children.length) sel.appendChild(og);
    });
    sel.addEventListener("change", function () {
      var i = parseInt(sel.value, 10);
      onChange(isNaN(i) ? 0 : i);
    });
    row.appendChild(el("label", "cplpw-sellabel", "Choose a pathway:"));
    row.appendChild(sel);
    var nDir = directory.length, nFeat = items.length - nDir;
    row.appendChild(el("span", "cplpw-selcount",
      nDir + " CCC baccalaureate degree" + (nDir === 1 ? "" : "s") + " + " + nFeat + " featured course map" + (nFeat === 1 ? "" : "s")));
    return { row: row, select: sel };
  }

  function render(root, data, live, dir, liveNote) {
    var featured = (data && data.programs) || [];
    var directory = (window.CPL_BACCALAUREATES && window.CPL_BACCALAUREATES.programs) || [];
    var items = [];
    featured.forEach(function (p) { items.push({ kind: "featured", prog: p }); });
    directory.forEach(function (p) { items.push({ kind: "directory", prog: p }); });
    if (!items.length) {
      clearNode(root);
      root.appendChild(el("div", "cplpw-empty", "No pathway definitions found (cpl_pathways_data.js)."));
      return;
    }
    var container = el("div", "cplpw");
    var body = el("div");
    function show(i) {
      var it = items[i] || items[0];
      if (it.kind === "directory") renderDirectory(body, it.prog, dir, directory, dir ? null : liveNote);
      else renderProgram(body, it.prog, live, liveNote);
    }
    var selector = null;
    if (items.length > 1) {
      selector = buildSelector(items, directory, function (i) { show(i); });
      container.appendChild(selector.row);
    }
    container.appendChild(body);
    clearNode(root);
    root.removeAttribute("style");
    root.appendChild(container);
    if (selector) selector.select.value = "0";
    show(0);
  }

  // ── Boot ──────────────────────────────────────────────────────────────────
  function activate() {
    ensureCss();
    var root = document.getElementById(ROOT_ID);
    if (!root) return;
    if (root.getAttribute("data-cplpw-rendered") === "1") return;
    root.setAttribute("data-cplpw-rendered", "1");

    var data = window.CPL_PATHWAYS || { programs: [] };
    var college = (data.programs && data.programs[0] && data.programs[0].college) || "Cerritos";

    function done(payload, note) {
      var live = null, dir = null;
      try { live = buildLiveIndexes(payload, college); } catch (e) { live = null; }
      try { dir = buildDirectoryIndex(payload); } catch (e) { dir = null; }
      render(root, data, live, dir, (live || dir) ? null : (note || "Live MAP articulation data unavailable — showing the curated snapshot."));
    }
    function withCer() {
      // Live CER payload (3 MB, lazy — the CER/MAP-Export tabs share the same file).
      if (window.CPL_CREDENTIAL_REFERENCE) {
        done(window.CPL_CREDENTIAL_REFERENCE);
      } else if (window.CPL_TABS && window.CPL_TABS.loadScript) {
        window.CPL_TABS.loadScript("credential_reference_data.js", "CPL_CREDENTIAL_REFERENCE", function () {
          done(window.CPL_CREDENTIAL_REFERENCE || null);
        });
      } else {
        done(null);
      }
    }
    // Directory tier: the per-baccalaureate cards (window.CPL_BACCALAUREATES).
    // Lazy-load it once (static, ~40 KB), then resolve the CER payload.
    if (window.CPL_BACCALAUREATES || !(window.CPL_TABS && window.CPL_TABS.loadScript)) {
      withCer();
    } else {
      window.CPL_TABS.loadScript("cpl_baccalaureates_data.js", "CPL_BACCALAUREATES", function () { withCer(); });
    }
  }

  window.CPL_PATHWAYS_TAB = {
    activate: activate,
    // exposed for tests
    _buildLiveIndexes: buildLiveIndexes,
    _resolvePathway: resolvePathway,
    _courseKey: courseKey,
    _exportPdf: exportPdf,
    _stages: STAGES,
    _buildDirectoryIndex: buildDirectoryIndex,
    _resolveDirectory: resolveDirectory,
  };
})();
